package com.example.crm.auth;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AuthIntegrationTest { @Autowired MockMvc mvc; @Test void registerLoginRefreshLogoutFlow() throws Exception {var register=mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"new-client\",\"password\":\"secret123\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();var refresh=register.replaceAll(".*\\\"refreshToken\\\":\\\"([^\\\"]+).*","$1");var login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"new-client\",\"password\":\"secret123\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var token=login.replaceAll(".*\\\"accessToken\\\":\\\"([^\\\"]+).*","$1");var ref=login.replaceAll(".*\\\"refreshToken\\\":\\\"([^\\\"]+).*","$1");mvc.perform(get("/api/customers").header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(post("/api/auth/refresh").contentType(MediaType.APPLICATION_JSON).content("{\"refreshToken\":\""+ref+"\"}")).andExpect(status().isOk());mvc.perform(post("/api/auth/logout").contentType(MediaType.APPLICATION_JSON).content("{\"refreshToken\":\""+refresh+"\"}")).andExpect(status().isNoContent());} }
